type Bag2ApplyHooks struct {
	OnCapacityChanged   func(oldValue, newValue int32)
	OnItemsPut          func(key uint64, oldValue, newValue *Item, replaced bool)
	OnItemsDelete       func(key uint64, oldValue *Item)
	OnItemsClear        func()
	OnItemsPatch        func(key uint64, oldValue, newValue *Item)
	OnItemsIdChanged    func(key uint64, oldValue, newValue uint64)
	OnItemsCountChanged func(key uint64, oldValue, newValue int32)
	OnItemsLevelChanged func(key uint64, oldValue, newValue int32)
	OnOrderAppend       func(index int, value uint64)
	OnOrderInsert       func(index int, value uint64)
	OnOrderStore        func(index int, oldValue, newValue uint64)
	OnOrderDelete       func(index int, oldValue uint64)
	OnOrderMove         func(from, to int)
	OnOrderClear        func()
}

const bag2StateDirtyCapacityWord uint32 = 0
const bag2StateDirtyCapacityMask uint64 = 1
const bag2StateDirtyItemsWord uint32 = 0
const bag2StateDirtyItemsMask uint64 = 2
const bag2StateDirtyOrderWord uint32 = 0
const bag2StateDirtyOrderMask uint64 = 4

type Bag2State struct {
	value        *Bag2
	dirty        [1]uint64
	markParent   func()
	itemsChanges bag2ItemsTracker
	orderChanges bag2OrderTracker
}

func NewBag2State(value *Bag2) *Bag2State {
	return newBag2State(value, nil)
}

func NewBag2StateWithParent(value *Bag2, markParent func()) *Bag2State {
	return newBag2State(value, markParent)
}

func newBag2State(value *Bag2, markParent func()) *Bag2State {
	state := &Bag2State{value: value, markParent: markParent}
	return state
}

func (s *Bag2State) GetRawValue() *Bag2 {
	return s.value
}

func (s *Bag2State) IsDirty() bool {
	return diff.AnyDirty(s.dirty[:])
}

func (s *Bag2State) GetCapacity() int32 {
	return s.value.Capacity
}

func (s *Bag2State) SetCapacity(value int32) {
	if s.value.Capacity == value {
		return
	}
	s.value.Capacity = value
	if diff.MarkDirty(&s.dirty[bag2StateDirtyCapacityWord], bag2StateDirtyCapacityMask) && s.markParent != nil {
		s.markParent()
	}
}

func (s *Bag2State) markItemsDirty() {
	if diff.MarkDirty(&s.dirty[bag2StateDirtyItemsWord], bag2StateDirtyItemsMask) && s.markParent != nil {
		s.markParent()
	}
}

func (s *Bag2State) Items() Bag2Items {
	return Bag2Items{state: s}
}

func (m Bag2Items) GetValue(key uint64) (Bag2ItemsValue, bool) {
	value, ok := m.state.value.Items[key]
	return Bag2ItemsValue{value: value, key: key, parent: m.state}, ok
}

func (m Bag2Items) Store(key uint64, value *Item) {
	value = proto.Clone(value).(*Item)
	if m.state.value.Items == nil {
		m.state.value.Items = make(map[uint64]*Item)
	}
	m.state.value.Items[key] = value
	if m.state.itemsChanges.Put(key) {
		m.state.markItemsDirty()
	}
}

func (m Bag2Items) Clear() {
	if len(m.state.value.Items) == 0 {
		return
	}
	m.state.value.Items = nil
	if m.state.itemsChanges.Clear() {
		m.state.markItemsDirty()
	}
}

func (m Bag2Items) Len() int {
	return len(m.state.value.Items)
}

func (m Bag2Items) Delete(key uint64) {
	if _, ok := m.state.value.Items[key]; !ok {
		return
	}
	delete(m.state.value.Items, key)
	if m.state.itemsChanges.Delete(key) {
		m.state.markItemsDirty()
	}
}

func (m Bag2Items) Range(yield func(uint64, Bag2ItemsValue) bool) {
	for key, value := range m.state.value.Items {
		if !yield(key, Bag2ItemsValue{value: value, key: key, parent: m.state}) {
			return
		}
	}
}

func (r Bag2ItemsValue) GetRawValue() *Item {
	return r.value
}

func (r Bag2ItemsValue) GetId() uint64 {
	return r.value.Id
}

func (r Bag2ItemsValue) SetId(value uint64) {
	if r.value.Id == value {
		return
	}
	r.value.Id = value
	dirty, first := r.parent.itemsChanges.Patch(r.key)
	if dirty != nil {
		diff.MarkDirty(&dirty[0], 1)
	}
	if first {
		r.parent.markItemsDirty()
	}
}

func (r Bag2ItemsValue) GetCount() int32 {
	return r.value.Count
}

func (r Bag2ItemsValue) SetCount(value int32) {
	if r.value.Count == value {
		return
	}
	r.value.Count = value
	dirty, first := r.parent.itemsChanges.Patch(r.key)
	if dirty != nil {
		diff.MarkDirty(&dirty[0], 2)
	}
	if first {
		r.parent.markItemsDirty()
	}
}

func (r Bag2ItemsValue) GetLevel() int32 {
	return r.value.Level
}

func (r Bag2ItemsValue) SetLevel(value int32) {
	if r.value.Level == value {
		return
	}
	r.value.Level = value
	dirty, first := r.parent.itemsChanges.Patch(r.key)
	if dirty != nil {
		diff.MarkDirty(&dirty[0], 4)
	}
	if first {
		r.parent.markItemsDirty()
	}
}

func (s *Bag2State) markOrderDirty() {
	if diff.MarkDirty(&s.dirty[bag2StateDirtyOrderWord], bag2StateDirtyOrderMask) && s.markParent != nil {
		s.markParent()
	}
}

func (s *Bag2State) Order() Bag2Order {
	return Bag2Order{state: s}
}

func (l Bag2Order) Len() int {
	return len(l.state.value.Order)
}

func (l Bag2Order) GetValue(index int) (uint64, bool) {
	if index < 0 || index >= len(l.state.value.Order) {
		var zero uint64
		return zero, false
	}
	return l.state.value.Order[index], true
}

func (l Bag2Order) Clear() {
	if len(l.state.value.Order) == 0 {
		return
	}
	l.state.value.Order = nil
	if l.state.orderChanges.Clear() {
		l.state.markOrderDirty()
	}
}

func (l Bag2Order) Store(index int, value uint64) {
	if l.state.value.Order[index] == value {
		return
	}
	l.state.value.Order[index] = value
	if l.state.orderChanges.Store(uint32(index), value) {
		l.state.markOrderDirty()
	}
}

func (l Bag2Order) Append(value uint64) {
	l.state.value.Order = append(l.state.value.Order, value)
	if l.state.orderChanges.Append(value) {
		l.state.markOrderDirty()
	}
}

func (l Bag2Order) Insert(index int, value uint64) {
	var zero uint64
	l.state.value.Order = append(l.state.value.Order, zero)
	copy(l.state.value.Order[index+1:], l.state.value.Order[index:len(l.state.value.Order)-1])
	l.state.value.Order[index] = value
	if l.state.orderChanges.Insert(uint32(index), value) {
		l.state.markOrderDirty()
	}
}

func (l Bag2Order) Delete(index int) {
	copy(l.state.value.Order[index:], l.state.value.Order[index+1:])
	l.state.value.Order = l.state.value.Order[:len(l.state.value.Order)-1]
	if l.state.orderChanges.Delete(uint32(index)) {
		l.state.markOrderDirty()
	}
}

func (l Bag2Order) Move(from int, to int) {
	if from == to {
		return
	}
	value := l.state.value.Order[from]
	if from < to {
		copy(l.state.value.Order[from:to], l.state.value.Order[from+1:to+1])
	} else {
		copy(l.state.value.Order[to+1:from+1], l.state.value.Order[to:from])
	}
	l.state.value.Order[to] = value
	if l.state.orderChanges.Move(uint32(from), uint32(to)) {
		l.state.markOrderDirty()
	}
}

func (l Bag2Order) Range(yield func(int, uint64) bool) {
	for index, value := range l.state.value.Order {
		if !yield(index, value) {
			return
		}
	}
}

func (s *Bag2State) WriteDiff(writer *diff.Writer) {
	if diff.HasDirty(s.dirty[bag2StateDirtyCapacityWord], bag2StateDirtyCapacityMask) {
		writer.Int32(1, s.value.Capacity)
	}
	if diff.HasDirty(s.dirty[bag2StateDirtyItemsWord], bag2StateDirtyItemsMask) {
		for index := range s.itemsChanges.changes {
			change := &s.itemsChanges.changes[index]
			switch change.operation {
			case diff.OperationClear:
				writer.Clear(2)
			case diff.OperationMapPut:
				data, err := proto.Marshal(s.value.Items[change.key])
				if err != nil {
					panic(err)
				}
				writer.MapPut(2, func(writer *diff.Writer) {
					writer.AppendUint64(change.key)
				}, func(writer *diff.Writer) {
					writer.AppendBytes(data)
				})
			case diff.OperationMapDelete:
				writer.MapDelete(2, func(writer *diff.Writer) {
					writer.AppendUint64(change.key)
				})
			case diff.OperationMapPatch:
				writer.MapPatch(2, func(writer *diff.Writer) {
					writer.AppendUint64(change.key)
				}, func(writer *diff.Writer) {
					if diff.HasDirty(change.dirty[0], 1) {
						writer.Uint64(1, s.value.Items[change.key].Id)
					}
					if diff.HasDirty(change.dirty[0], 2) {
						writer.Int32(2, s.value.Items[change.key].Count)
					}
					if diff.HasDirty(change.dirty[0], 4) {
						writer.Int32(3, s.value.Items[change.key].Level)
					}
				})
			}
		}
	}
	if diff.HasDirty(s.dirty[bag2StateDirtyOrderWord], bag2StateDirtyOrderMask) {
		for _, change := range s.orderChanges.changes {
			switch change.operation {
			case diff.OperationClear:
				writer.Clear(3)
			case diff.OperationListAppend:
				writer.ListAppend(3, func(writer *diff.Writer) {
					writer.AppendUint64(change.value)
				})
			case diff.OperationListInsert:
				writer.ListInsert(3, change.index, func(writer *diff.Writer) {
					writer.AppendUint64(change.value)
				})
			case diff.OperationListSet:
				writer.ListSet(3, change.index, func(writer *diff.Writer) {
					writer.AppendUint64(change.value)
				})
			case diff.OperationListDelete:
				writer.ListDelete(3, change.index)
			case diff.OperationListMove:
				writer.ListMove(3, change.index, change.to)
			}
		}
	}
}

func ApplyBag2Diff(value *Bag2, data []byte) error {
	return applyBag2Diff(value, data, nil)
}

func ApplyBag2DiffWithHooks(value *Bag2, data []byte, hooks *Bag2ApplyHooks) error {
	return applyBag2Diff(value, data, hooks)
}

func applyBag2Diff(value *Bag2, data []byte, hooks *Bag2ApplyHooks) error {
	reader := diff.NewReader(data)
	for {
		fieldNumber, operation, payload, ok, err := reader.Next()
		if err != nil || !ok {
			return err
		}
		switch fieldNumber {
		case 1:
			if operation != diff.OperationSetVarint {
				return diff.ErrInvalidData
			}
			oldValue := value.Capacity
			value.Capacity = diff.DecodeInt32(payload)
			if hooks != nil && hooks.OnCapacityChanged != nil {
				hooks.OnCapacityChanged(oldValue, value.Capacity)
			}
		case 2:
			if operation == diff.OperationClear {
				if len(payload) != 0 {
					return diff.ErrInvalidData
				}
				value.Items = nil
				if hooks != nil && hooks.OnItemsClear != nil {
					hooks.OnItemsClear()
				}
				break
			}
			valueReader := diff.NewValueReader(payload)
			key := valueReader.Uint64()
			switch operation {
			case diff.OperationMapPut:
				itemData := valueReader.Bytes()
				item := &Item{}
				if err := proto.Unmarshal(itemData, item); err != nil {
					return err
				}
				if valueReader.Err() != nil || !valueReader.Done() {
					return diff.ErrInvalidData
				}
				oldItem, replaced := value.Items[key]
				if value.Items == nil {
					value.Items = make(map[uint64]*Item)
				}
				value.Items[key] = item
				if hooks != nil && hooks.OnItemsPut != nil {
					var oldHookValue *Item
					if oldItem != nil {
						oldHookValue = proto.Clone(oldItem).(*Item)
					}
					hooks.OnItemsPut(key, oldHookValue, proto.Clone(item).(*Item), replaced)
				}
			case diff.OperationMapDelete:
				if valueReader.Err() != nil || !valueReader.Done() {
					return diff.ErrInvalidData
				}
				oldItem, existed := value.Items[key]
				delete(value.Items, key)
				if existed && hooks != nil && hooks.OnItemsDelete != nil {
					hooks.OnItemsDelete(key, proto.Clone(oldItem).(*Item))
				}
			case diff.OperationMapPatch:
				patch := valueReader.Remaining()
				if valueReader.Err() != nil {
					return diff.ErrInvalidData
				}
				item := value.Items[key]
				var oldItem *Item
				if hooks != nil && (hooks.OnItemsPatch != nil || hooks.OnItemsIdChanged != nil || hooks.OnItemsCountChanged != nil || hooks.OnItemsLevelChanged != nil) && item != nil {
					oldItem = proto.Clone(item).(*Item)
				}
				if item == nil {
					item = &Item{}
					if value.Items == nil {
						value.Items = make(map[uint64]*Item)
					}
					value.Items[key] = item
				}
				if err := ApplyItemDiff(item, patch); err != nil {
					return err
				}
				if hooks != nil {
					if hooks.OnItemsPatch != nil {
						hooks.OnItemsPatch(key, oldItem, proto.Clone(item).(*Item))
					}
					if hooks.OnItemsIdChanged != nil && oldItem.GetId() != item.GetId() {
						hooks.OnItemsIdChanged(key, oldItem.GetId(), item.GetId())
					}
					if hooks.OnItemsCountChanged != nil && oldItem.GetCount() != item.GetCount() {
						hooks.OnItemsCountChanged(key, oldItem.GetCount(), item.GetCount())
					}
					if hooks.OnItemsLevelChanged != nil && oldItem.GetLevel() != item.GetLevel() {
						hooks.OnItemsLevelChanged(key, oldItem.GetLevel(), item.GetLevel())
					}
				}
			default:
				return diff.ErrInvalidData
			}
		case 3:
			valueReader := diff.NewValueReader(payload)
			switch operation {
			case diff.OperationClear:
				value.Order = nil
				if hooks != nil && hooks.OnOrderClear != nil {
					hooks.OnOrderClear()
				}
			case diff.OperationListAppend:
				item := valueReader.Uint64()
				index := len(value.Order)
				value.Order = append(value.Order, item)
				if hooks != nil && hooks.OnOrderAppend != nil {
					hooks.OnOrderAppend(index, item)
				}
			case diff.OperationListInsert:
				index := int(valueReader.Uint32())
				item := valueReader.Uint64()
				var zero uint64
				value.Order = append(value.Order, zero)
				copy(value.Order[index+1:], value.Order[index:len(value.Order)-1])
				value.Order[index] = item
				if hooks != nil && hooks.OnOrderInsert != nil {
					hooks.OnOrderInsert(index, item)
				}
			case diff.OperationListSet:
				index := int(valueReader.Uint32())
				item := valueReader.Uint64()
				oldItem := value.Order[index]
				value.Order[index] = item
				if hooks != nil && hooks.OnOrderStore != nil {
					hooks.OnOrderStore(index, oldItem, item)
				}
			case diff.OperationListDelete:
				index := int(valueReader.Uint32())
				oldItem := value.Order[index]
				copy(value.Order[index:], value.Order[index+1:])
				value.Order = value.Order[:len(value.Order)-1]
				if hooks != nil && hooks.OnOrderDelete != nil {
					hooks.OnOrderDelete(index, oldItem)
				}
			case diff.OperationListMove:
				from := int(valueReader.Uint32())
				to := int(valueReader.Uint32())
				item := value.Order[from]
				if from < to {
					copy(value.Order[from:to], value.Order[from+1:to+1])
				} else {
					copy(value.Order[to+1:from+1], value.Order[to:from])
				}
				value.Order[to] = item
				if hooks != nil && hooks.OnOrderMove != nil {
					hooks.OnOrderMove(from, to)
				}
			default:
				return diff.ErrInvalidData
			}
			if valueReader.Err() != nil || !valueReader.Done() {
				return diff.ErrInvalidData
			}
		}
	}
}

func (s *Bag2State) ClearDirty() {
	diff.ClearDirty(s.dirty[:])
	s.itemsChanges.ClearDirty()
	s.orderChanges.ClearDirty()
}

type ItemApplyHooks struct {
	OnIdChanged    func(oldValue, newValue uint64)
	OnCountChanged func(oldValue, newValue int32)
	OnLevelChanged func(oldValue, newValue int32)
}

const itemStateDirtyIdWord uint32 = 0
const itemStateDirtyIdMask uint64 = 1
const itemStateDirtyCountWord uint32 = 0
const itemStateDirtyCountMask uint64 = 2
const itemStateDirtyLevelWord uint32 = 0
const itemStateDirtyLevelMask uint64 = 4

type ItemState struct {
	value      *Item
	dirty      [1]uint64
	markParent func()
}

func NewItemState(value *Item) *ItemState {
	return newItemState(value, nil)
}

func NewItemStateWithParent(value *Item, markParent func()) *ItemState {
	return newItemState(value, markParent)
}

func newItemState(value *Item, markParent func()) *ItemState {
	state := &ItemState{value: value, markParent: markParent}
	return state
}

func (s *ItemState) GetRawValue() *Item {
	return s.value
}

func (s *ItemState) IsDirty() bool {
	return diff.AnyDirty(s.dirty[:])
}

func (s *ItemState) GetId() uint64 {
	return s.value.Id
}

func (s *ItemState) SetId(value uint64) {
	if s.value.Id == value {
		return
	}
	s.value.Id = value
	if diff.MarkDirty(&s.dirty[itemStateDirtyIdWord], itemStateDirtyIdMask) && s.markParent != nil {
		s.markParent()
	}
}

func (s *ItemState) GetCount() int32 {
	return s.value.Count
}

func (s *ItemState) SetCount(value int32) {
	if s.value.Count == value {
		return
	}
	s.value.Count = value
	if diff.MarkDirty(&s.dirty[itemStateDirtyCountWord], itemStateDirtyCountMask) && s.markParent != nil {
		s.markParent()
	}
}

func (s *ItemState) GetLevel() int32 {
	return s.value.Level
}

func (s *ItemState) SetLevel(value int32) {
	if s.value.Level == value {
		return
	}
	s.value.Level = value
	if diff.MarkDirty(&s.dirty[itemStateDirtyLevelWord], itemStateDirtyLevelMask) && s.markParent != nil {
		s.markParent()
	}
}

func (s *ItemState) WriteDiff(writer *diff.Writer) {
	if diff.HasDirty(s.dirty[itemStateDirtyIdWord], itemStateDirtyIdMask) {
		writer.Uint64(1, s.value.Id)
	}
	if diff.HasDirty(s.dirty[itemStateDirtyCountWord], itemStateDirtyCountMask) {
		writer.Int32(2, s.value.Count)
	}
	if diff.HasDirty(s.dirty[itemStateDirtyLevelWord], itemStateDirtyLevelMask) {
		writer.Int32(3, s.value.Level)
	}
}

func ApplyItemDiff(value *Item, data []byte) error {
	return applyItemDiff(value, data, nil)
}

func ApplyItemDiffWithHooks(value *Item, data []byte, hooks *ItemApplyHooks) error {
	return applyItemDiff(value, data, hooks)
}

func applyItemDiff(value *Item, data []byte, hooks *ItemApplyHooks) error {
	reader := diff.NewReader(data)
	for {
		fieldNumber, operation, payload, ok, err := reader.Next()
		if err != nil || !ok {
			return err
		}
		switch fieldNumber {
		case 1:
			if operation != diff.OperationSetVarint {
				return diff.ErrInvalidData
			}
			oldValue := value.Id
			value.Id = diff.DecodeUint64(payload)
			if hooks != nil && hooks.OnIdChanged != nil {
				hooks.OnIdChanged(oldValue, value.Id)
			}
		case 2:
			if operation != diff.OperationSetVarint {
				return diff.ErrInvalidData
			}
			oldValue := value.Count
			value.Count = diff.DecodeInt32(payload)
			if hooks != nil && hooks.OnCountChanged != nil {
				hooks.OnCountChanged(oldValue, value.Count)
			}
		case 3:
			if operation != diff.OperationSetVarint {
				return diff.ErrInvalidData
			}
			oldValue := value.Level
			value.Level = diff.DecodeInt32(payload)
			if hooks != nil && hooks.OnLevelChanged != nil {
				hooks.OnLevelChanged(oldValue, value.Level)
			}
		}
	}
}

func (s *ItemState) ClearDirty() {
	diff.ClearDirty(s.dirty[:])
}
